CREATE OR REPLACE VIEW Emp_VEmpShort AS
 SELECT
        E.Id     Emp_Id    ,
        E.Num    Emp_Num   , E.Name     Emp_Name   ,
        E.Num ||'-'||E.Name             Emp_Fname  ,
        Dept.Id  Dept_Id   , Dept.Name  Dept_Name  ,
        Sect.Id  Sect_Id   , Sect.Name  Sect_Name  ,
        Job.Id   Job_Id    , Job.Name   Job_Name   ,
        Lvl.Id   Level_Id  , Lvl.Name   Level_Name ,
        Spec1.Id Spc1_Id   , Spec1.Name Spc1_Name  ,
        Spec2.Id Spc2_Id   , Spec2.Name Spc2_Name  ,
        Spec3.Id Spc3_Id   , Spec3.Name Spc3_Name  ,
        Spec4.Id Spc4_Id   , Spec4.Name Spc4_Name
   FROM Emp_Emp            E    ,
        Emp_Cod_Department Dept ,
        Emp_Cod_Section    Sect ,
        Emp_Cod_Job        Job  ,
        Emp_Cod_Level      Lvl  ,
        Emp_Cod_Spec1      Spec1,
        Emp_Cod_Spec2      Spec2,
        Emp_Cod_Spec3      Spec3,
        Emp_Cod_Spec4      Spec4
  WHERE E.Dept_Id =Dept.Id
    AND E.Sect_Id =Sect.Id 
    AND E.Job_Id  =Job.Id
    AND E.Level_Id=Lvl.Id
    AND E.Spc1_Id =Spec1.Id
    AND E.Spc2_Id =Spec2.Id
    AND E.Spc3_Id =Spec3.Id
    AND E.Spc4_Id =Spec4.Id;

CREATE OR REPLACE VIEW Emp_VLeaves AS
  SELECT
        E.Emp_Id ,
        E.Emp_Num, E.Emp_Name , E.Emp_Fname,
        E.Dept_Id, E.Dept_Name, E.Sect_Id  , E.Sect_Name ,
        E.Job_Id , E.Job_Name , E.Level_Id , E.Level_Name,
        E.Spc1_Id, E.Spc1_Name, E.Spc2_Id  , E.Spc2_Name ,
        E.Spc3_Id, E.Spc3_Name, E.Spc4_Id  , E.Spc4_Name ,
        M.Id     ,
        M.Num      Leave_Num  , M.Ddate      Leave_Ddate ,
        Typ.Id     Type_Id    , Typ.Name     Type_Name   ,
        M.Sdate    Leave_Sdate, M.Shour      Leave_Shour , M.Sminute Leave_Sminute,
        M.Edate    Leave_Edate, M.Ehour      Leave_Ehour , M.Eminute Leave_Eminute,
        M.Rem      Leave_Rem  , M.Req_Id     Leave_Req_Id,
       (M.Edate - M.Sdate)      Leave_Days,
       ((M.Ehour * 60) + M.Eminute) - ((M.Shour * 60) + M.Sminute)   Leave_Minutes
   FROM Emp_Vempshort E  ,
        Emp_Leave     M  ,
        Emp_Cod_Leave Typ
  WHERE M.Emp_Id  =E.Emp_Id
    And M.Type_Id =Typ.Id;

