CREATE OR REPLACE VIEW Emp_VChGrade AS
 SELECT 
        E.Emp_Id     ,
        E.Emp_Num    , E.Emp_Name , E.Emp_Fname    ,
        E.Dept_Id    , E.Dept_Name, E.Sect_Id      , E.Sect_Name   ,
        E.Job_Id     , E.Job_Name , E.Level_Id     , E.Level_Name  ,
        E.Spc1_Id    , E.Spc1_Name, E.Spc2_Id      , E.Spc2_Name   ,
        E.Spc3_Id    , E.Spc3_Name, E.Spc4_Id      , E.Spc4_Name   ,
        Ch.Id          CGrad_Id   ,
        Ch.Num         CGrad_Num  , Ch.Ddate       CGrad_Ddate ,
        O.Grdt_Id      TGrad_OId  ,
        O.Grp_Id       Grp_OId    , O.Grp_Name     Grp_OName   ,
        O.Degree_Id    Degree_OId , O.Degree_Name  Degree_OName,
        N.Grdt_Id      TGrad_NId  ,
        N.Grp_Id       Grp_NId    , N.Grp_Name     Grp_NName   ,
        N.Degree_Id    Degree_NId , N.Degree_Name  Degree_NName,
        Ch.Days        CGrad_Days , Ch.Sdate       CGrad_SDate ,
        Ch.Rem         CGrad_Rem
   FROM Emp_Vempshort  E ,
        Emp_ChGrade    Ch,
        Emp_Vgradtmplt O ,
        Emp_Vgradtmplt N
  WHERE Ch.Emp_Id   =E.Emp_Id
    AND Ch.Tgrad_Oid=O.Grdt_Id
    AND Ch.Tgrad_Nid=N.Grdt_Id;

