CREATE OR REPLACE VIEW Emp_VLoan AS
 SELECT 
        L.Id       Loan_Id   ,
        L.Tamt     Loan_Tamt , L.Mamt       Loan_Mamt  ,
        L.Bamt     Loan_Bamt , L.Num        Loan_Num   ,
        L.Ddate    Loan_Ddate, L.Sdate      Loan_Sdate ,
        L.Edate    Loan_Edate, L.Rem        Loan_Rem   ,
        E.Emp_Id   Emp_Id    , E.Emp_Num    Emp_Num    ,
        E.Emp_Name Emp_Name  , E.Emp_Fname  Emp_Fname  ,
        E.Dept_Id  Dept_Id   , E.Dept_Name  Dept_Name  ,
        E.Sect_Id  Sect_Id   , E.Sect_Name  Sect_Name  ,
        E.Job_Id   Job_Id    , E.Job_Name   Job_Name   ,
        E.Level_Id Level_Id  , E.Level_Name Level_Name ,
        E.Spc1_Id  Spc1_Id   , E.Spc1_Name  Spc1_Name  ,
        E.Spc2_Id  Spc2_Id   , E.Spc2_Name  Spc2_Name  ,
        E.Spc3_Id  Spc3_Id   , E.Spc3_Name  Spc3_Name  ,
        E.Spc4_Id  Spc4_Id   , E.Spc4_Name  Spc4_Name  ,
        ST.Id      Status_Id , ST.Name      Status_Name,
        YN.Id      Yesno_Id  , YN.Name      Yesno_Name
   FROM Emp_Loan       L ,
        Emp_VEmpShort  E ,
        Phs_Cod_Status ST,
        Phs_Cod_Yesno  YN  
  WHERE L.Emp_Id   =E.Emp_Id
    AND L.Status_Id=ST.Id
    AND L.Pflg_Id  =YN.Id;

CREATE OR REPLACE VIEW Emp_VPLoan AS
 SELECT 
        L.Id       Loan_Id      ,
        L.Tamt     Loan_Tamt    , L.Mamt       Loan_Mamt  ,
        L.Bamt     Loan_Bamt    , L.Num        Loan_Num   ,
        L.Ddate    Loan_Ddate   , L.Sdate      Loan_Sdate ,
        L.Edate    Loan_Edate   , L.Rem        Loan_Rem   ,
        PL.Id      Ploan_Id     , PL.Src_Id    Ploan_Srcid,
        PL.Tsal_Id Ploan_Tsal_Id, PL.Amt       Ploan_Amt  ,
        PL.Num     Ploan_Num    , PL.Ddate     Ploan_Ddate,
        PL.Rem     Ploan_Rem    ,
        E.Emp_Id   Emp_Id       , E.Emp_Num    Emp_Num    ,
        E.Emp_Name Emp_Name     , E.Emp_Fname  Emp_Fname  ,
        E.Dept_Id  Dept_Id      , E.Dept_Name  Dept_Name  ,
        E.Sect_Id  Sect_Id      , E.Sect_Name  Sect_Name  ,
        E.Job_Id   Job_Id       , E.Job_Name   Job_Name   ,
        E.Level_Id Level_Id     , E.Level_Name Level_Name ,
        E.Spc1_Id  Spc1_Id      , E.Spc1_Name  Spc1_Name  ,
        E.Spc2_Id  Spc2_Id      , E.Spc2_Name  Spc2_Name  ,
        E.Spc3_Id  Spc3_Id      , E.Spc3_Name  Spc3_Name  ,
        E.Spc4_Id  Spc4_Id      , E.Spc4_Name  Spc4_Name  ,
        ST.Id      Status_Id    , ST.Name      Status_Name,
        YN.Id      Yesno_Id     , YN.Name      Yesno_Name
   FROM Emp_Loan       L ,
        Emp_Ploan      PL,
        Emp_Vempshort  E ,
        Phs_Cod_Status ST,
        Phs_Cod_Yesno  YN
  WHERE PL.Loan_Id =L.Id
    AND L.Emp_Id   =E.Emp_Id
    AND L.Status_Id=ST.Id
    AND L.Pflg_Id  =YN.Id;

CREATE OR REPLACE VIEW Emp_VDed AS
 SELECT
        D.Id  Ded_Id    , 
        D.Num Ded_Num   , D.Name  Ded_Name    ,
        AM.Id AmtType_Id, AM.Name AmtType_Name,
        TB.Id TaxBrkt_Id, TB.Name TaxBrkt_Name,
        TP.Id TaxPay_Id , TP.Name TaxPay_Name ,
        D.Amt Ded_Amt
   FROM Emp_Ded         D ,
        Phs_Cod_AmtType AM, 
        Emp_TaxBrkt     TB,
        Emp_Cod_TaxPay  TP 
  WHERE D.Type_Id   =AM.Id
    AND D.Brkt_Id   =TB.Id
    AND D.Taxpay_Id =TP.Id;

CREATE OR REPLACE VIEW Emp_VEDed AS
 SELECT
       	D.Id       Ded_Id    , 
        D.Num      Ded_Num   , D.Name       Ded_Name    ,
        AM.Id      AmtType_Id, AM.Name      AmtType_Name,
        TB.Id      TaxBrkt_Id, TB.Name      TaxBrkt_Name,
        TP.Id      TaxPay_Id , TP.Name      TaxPay_Name ,
        D.Amt      Ded_Amt   ,
        ED.Id      EDed_Id   ,
        E.Emp_Id   Emp_Id    , E.Emp_Num    Emp_Num     ,
        E.Emp_Name Emp_Name  , E.Emp_Fname  Emp_Fname   ,
        E.Dept_Id  Dept_Id   , E.Dept_Name  Dept_Name   ,
        E.Sect_Id  Sect_Id   , E.Sect_Name  Sect_Name   ,
        E.Job_Id   Job_Id    , E.Job_Name   Job_Name    ,
        E.Level_Id Level_Id  , E.Level_Name Level_Name  ,
        E.Spc1_Id  Spc1_Id   , E.Spc1_Name  Spc1_Name   ,
        E.Spc2_Id  Spc2_Id   , E.Spc2_Name  Spc2_Name   ,
        E.Spc3_Id  Spc3_Id   , E.Spc3_Name  Spc3_Name   ,
        E.Spc4_Id  Spc4_Id   , E.Spc4_Name  Spc4_Name   ,
        ED.Sdate   Start_Date, ED.Edate     End_Date    ,
        Cs.Id      Status_Id , Cs.Name      Status_Name ,
        ED.Pamt    Eded_Pamt , ED.Rem       Eded_Rem
   FROM Emp_Ded         D ,
        Emp_Eded        Ed,
        Emp_Vempshort   E ,
        Phs_Cod_Amttype Am, 
        Emp_Taxbrkt     Tb,
        Emp_Cod_Taxpay  Tp, 
        Phs_Cod_Status  Cs
  WHERE ED.Ded_Id   =D.Id
    AND D.Type_Id   =AM.Id
    AND D.Brkt_Id   =TB.Id
    AND D.Taxpay_Id =TP.Id
    AND ED.Emp_Id   =E.Emp_Id
    AND ED.Status_Id=Cs.Id;

CREATE OR REPLACE VIEW Emp_VCom AS
 SELECT
        C.Id   Comp_Id   , 
        C.Num  Comp_Num  , C.Name  Comp_Name   ,
        CT.Id  ComType_Id, CT.Name ComType_Name,
        AM.Id  AmtType_Id, AM.Name AmtType_Name,
        TB.Id  TaxBrkt_Id, TB.Name TaxBrkt_Name,
        TX.Id  TaxPay_Id , TX.Name TaxPay_Name ,
        C.Pamt Comp_Pamt
   FROM Emp_Com         C ,
        Phs_Cod_AmtType AM, 
        Emp_TaxBrkt     TB,
        Emp_Cod_TaxPay  TX,
        Emp_Cod_ComType CT
  WHERE C.Type_Id   =AM.Id
    AND C.Brkt_Id   =TB.Id
    AND C.TaxPay_Id =TX.Id
    AND C.ComType_Id=CT.Id;

CREATE OR REPLACE VIEW Emp_VECom AS 
 SELECT
        C.Id       Comp_Id   , 
        C.Num      Comp_Num  , C.Name       Comp_Name   ,
        CT.Id      ComType_Id, CT.Name      ComType_Name,
        AM.Id      AmtType_Id, AM.Name      AmtType_Name,
        TB.Id      TaxBrkt_Id, TB.Name      TaxBrkt_Name,
        TX.Id      TaxPay_Id , TX.Name      TaxPay_Name ,
        C.Pamt     Comp_Pamt ,
        EC.Id      EComp_Id  ,
        E.Emp_Id   Emp_Id    , E.Emp_Num    Emp_Num     ,
        E.Emp_Name Emp_Name  , E.Emp_Fname  Emp_Fname   ,
        E.Dept_Id  Dept_Id   , E.Dept_Name  Dept_Name   ,
        E.Sect_Id  Sect_Id   , E.Sect_Name  Sect_Name   ,
        E.Job_Id   Job_Id    , E.Job_Name   Job_Name    ,
        E.Level_Id Level_Id  , E.Level_Name Level_Name  ,
        E.Spc1_Id  Spc1_Id   , E.Spc1_Name  Spc1_Name   ,
        E.Spc2_Id  Spc2_Id   , E.Spc2_Name  Spc2_Name   ,
        E.Spc3_Id  Spc3_Id   , E.Spc3_Name  Spc3_Name   ,
        E.Spc4_Id  Spc4_Id   , E.Spc4_Name  Spc4_Name   ,
        EC.Sdate   Start_Date, EC.Edate     End_Date    ,
        CS.Id      Status_Id , CS.Name      Status_Name ,
        EC.Pamt    EComp_Pamt, EC.Rem       EComp_Rem
   FROM Emp_Com         C ,
        Emp_ECom        EC,
        Emp_VEmpShort   E ,
        Phs_Cod_AmtType AM, 
        Emp_TaxBrkt     TB,
        Emp_Cod_TaxPay  TX,
        Emp_Cod_ComType CT,
        Phs_Cod_Status  CS
  WHERE EC.Com_Id   =C.Id
    AND C.Type_Id   =AM.Id
    AND C.Brkt_Id   =TB.Id
    AND C.TaxPay_Id =TX.Id
    AND EC.Emp_Id   =E.Emp_Id
    AND C.Comtype_Id=CT.Id
    AND EC.Status_Id=CS.Id;

CREATE OR REPLACE VIEW Emp_VEmpGradTmplt AS 
 SELECT
        V.Grdt_Id   Grdt_Id  ,
        V.Grp_Id    Grp_Id   , V.Grp_Name    Grp_Name   ,
        V.Degree_Id Degree_Id, V.Degree_Name Degree_Name,
        E.Id        Emp_Id   , E.Num         Emp_Num    ,
        E.Name      Emp_Name         
   FROM Emp_VGradTmplt V,
        Emp_Emp        E
  WHERE E.TGrad_Id=V.Grdt_Id;

CREATE OR REPLACE VIEW Emp_Vsalcalc As
 SELECT
        S.Id                 Sal_Id           , S.nYear         Sal_Year         ,
        S.nMonth             Sal_Month        , S.Status_Id     Status_Id        ,
        E.Id                 Emp_Id           , E.Num           Emp_Num          ,
        E.Name               Emp_Name         ,
        E.Num||'-'||E.Name   Emp_Fname        ,
        Dept.Id              Dept_Id          , Dept.Name       Dept_Name        ,
        Sect.Id              Sect_Id          , Sect.Name       Sect_Name        ,
        Job.Id               Job_Id           , Job.Name        Job_Name         ,
        Lvl.Id               Level_Id         , Lvl.Name        Level_Name       ,
        Spec1.Id             Spc1_Id          , Spec1.Name      Spc1_Name        ,
        Spec2.Id             Spc2_Id          , Spec2.Name      Spc2_Name        ,
        Spec3.Id             Spc3_Id          , Spec3.Name      Spc3_Name        ,
        Spec4.Id             Spc4_Id          , Spec4.Name      Spc4_Name        ,
        Cod.Id               Bankstatus_Id    , Cod.Name        Bankstatus_Name  ,
        E.Bankacc            Bankacc          , E.Bankname      Bankname         ,
        C.Id                 TSal_Id          ,
        C.Session_Id         Session_Id       ,
        C.Sal                Sal_Sal          , C.FSal          Sal_FSal         ,
        C.Tam                Sal_Tam          , C.WSal          Sal_WSal         ,
        C.Net                Sal_Net          , C.nRound        Sal_Round        ,
        C.Getam              Sal_Getam        , C.Gbtam1        Sal_Gbtam1       ,
        C.Gbtam2             Sal_Gbtam2       , C.Gbtam3        Sal_Gbtam3       ,
        C.Gaetam             Sal_Gaetam       , C.Gabtam1       Sal_Gabtam1      ,
        C.Gabtam2            Sal_Gabtam2      , C.Gabtam3       Sal_Gabtam3      ,
        C.GtamStatus_Id      Sal_GtamStatus_Id, C.Gtaxstatus_Id Sal_GtaxStatus_Id,
        C.Gtaxfree           Sal_GTaxFree     , C.Gtax          Sal_GTax         ,
        C.Comp               Sal_Comp         , C.Ded           Sal_Ded          ,
        C.AddAdd             Sal_AddAdd       , C.AddSal        Sal_AddSal       ,
        C.SubAdd             Sal_SubAdd       , C.SubSal        Sal_SubSal       ,
        C.Cons               Sal_Cons         , C.Salcons       Sal_SalCons      ,
        C.Addcons            Sal_AddCons      , C.Pun           Sal_Pun          ,
        C.Salpun             Sal_SalPun       , C.AddPun        Sal_AddPun       ,
        C.Dbt                Sal_Dbt          , C.Loan          Sal_Loan         ,
        C.nAddPrice          Sal_nAddPrice    , C.dAddPrice     Sal_dAddPrice    ,
        C.wAddPrice          Sal_wAddPrice    , C.hAddPrice     Sal_hAddPrice    ,
        C.dAdd               Sal_dAdd         , C.nAdd          Sal_nAdd         ,
        C.wAdd               Sal_wAdd         , C.hAdd          Sal_hAdd         ,
        C.nAddamt            Sal_nAddAmt      , C.dAddAmt       Sal_dAddAmt      ,
        C.wAddamt            Sal_wAddAmt      , C.hAddAmt       Sal_hAddAmt      ,
        C.nDels              Sal_nDels        , C.nAbs          Sal_nAbs         ,
        C.nSick              Sal_nSick        , C.nPar          Sal_nPar         ,
        C.nSick70            Sal_nSick70      , C.nSick80       Sal_nSick80      , 
        C.nNPay              Sal_nnPay        , C.DelAmt        Sal_DelAmt       ,
        C.Absamt             Sal_Absamt       , C.Sickamt       Sal_SickAmt      ,
        C.Sickamt70          Sal_SickAmt70    , C.Sickamt80     Sal_SickAmt80    ,
        C.ParAmt             Sal_ParAmt       , C.nPayAmt       Sal_nPayAmt      ,
        C.Rem                Sal_Rem          , C.Taxablesal    Sal_TaxableSal
   From Emp_SalCalc        C    ,
        Emp_Sal            S    ,
        Emp_Emp            E    ,
        Phs_Cod_Yesno      Cod  ,
        Emp_Cod_Department Dept ,
        Emp_Cod_Section    Sect ,
        Emp_Cod_Job        Job  ,
        Emp_Cod_Level      Lvl  ,
        Emp_Cod_Spec1      Spec1,
        Emp_Cod_Spec2      Spec2,
        Emp_Cod_Spec3      Spec3,
        Emp_Cod_Spec4      Spec4
  Where C.Sal_Id        =S.Id
    And C.Emp_Id        =E.Id
    And  E.Bankstatus_Id =Cod.Id        
    And E.Dept_Id       =Dept.Id
    AND E.Sect_Id       =Sect.Id 
    AND E.Job_Id        =Job.Id
    AND E.Level_Id      =Lvl.Id
    AND E.Spc1_Id       =Spec1.Id
    AND E.Spc2_Id       =Spec2.Id
    AND E.Spc3_Id       =Spec3.Id
    AND E.Spc4_Id       =Spec4.Id;

CREATE OR REPLACE VIEW Emp_VAosal As
 SELECT                 
        Aosal.Id         Aosal_Id       , Aosal.Num          Aosal_Num        ,
        Aosal.Ddate      Aosal_Ddate    , Aosal.Docn         Aosal_Docn       ,
        Aosal.Docd       Aosal_Docd     ,
        Aosalemp.Id      Aosalemp_Id    , Aosalemp.Sal       Aosalemp_Sal     ,
        Aosalemp.Amt     Aosalemp_Amt   , Aosalemp.Rem       Aosalemp_Rem     ,
        Emp.Emp_Id       Emp_Id         , Emp.Emp_Num        Emp_Num          ,
        Emp.Emp_Name     Emp_Name       , Emp.Emp_Fname      Emp_Fname        ,
        Emp.Dept_Id      Dept_Id        , Emp.Dept_Name      Dept_Name        ,
        Emp.Sect_Id      Sect_Id        , Emp.Sect_Name      Sect_Name        ,
        Emp.Job_Id       Job_Id         , Emp.Job_Name       Job_Name         ,
        Emp.Level_Id     Level_Id       , Emp.Level_Name     Level_Name       ,
        Emp.Spc1_Id      Spc1_Id        , Emp.Spc1_Name      Spc1_Name        ,
        Emp.Spc2_Id      Spc2_Id        , Emp.Spc2_Name      Spc2_Name        ,
        Emp.Spc3_Id      Spc3_Id        , Emp.Spc3_Name      Spc3_Name        ,
        Emp.Spc4_Id      Spc4_Id        , Emp.Spc4_Name      Spc4_Name        ,
        Cod_Aff.Id       Cod_Aff_Id     , Cod_Aff.Name       Cod_Aff_Name     ,
        Cod_Affsal.Id    Cod_Affsal_Id  , Cod_Affsal.Name    Cod_Affsal_Name  ,
        Cod_Chngtype.Id  Cod_Chngtype_Id, Cod_Chngtype.Name  Cod_Chngtype_Name,
        Taxbrkt.Id       Taxbrkt_Id     , Taxbrkt.Name       Taxbrkt_Name     ,
        Aosal.Nyear      Aosal_Nyear    ,
        Aosal.Nmonth     Aosal_Nmonth   ,
        Aosal.Perc       Aosal_Perc     ,
        Aosal.Amt        Aosal_Amt      ,
        Aosal.Nmin       Aosal_Nmin     ,
        Aosal.Nmax       Aosal_Nmax     ,
        Aosal.Rem        Aosal_Rem
   From Emp_Aosal        Aosal       ,
        Emp_Aosalemp      Aosalemp   ,
        Emp_Cod_Aff      Cod_Aff     ,
        Emp_Cod_Affsal   Cod_Affsal  ,
        Emp_Cod_Chngtype Cod_Chngtype,
        Emp_Taxbrkt      Taxbrkt     ,
        Emp_Vempshort    Emp  
  Where Aosal.Addto_Id   = Cod_Aff.Id
    And Aosal.Saltyp_Id  = Cod_Affsal.Id
    And Aosal.Type_Id    = Cod_Chngtype.Id
    And Aosal.Brkt_Id    = Taxbrkt.Id
    AND Aosalemp.ASAL_ID = Aosal.Id
    AND Aosalemp.EMP_ID  = Emp.Emp_Id;

CREATE OR REPLACE VIEW Emp_VCSal As
 SELECT                 
        C.Id         Csal_Id    , C.Num          Csal_Num     ,
        C.Ddate      Csal_Ddate , C.Docn         Csal_Docn    ,
        C.Docd       Csal_Docd  , CE.Id          CSal_TId     ,
        CE.Osal      CSal_Osal  , CE.Chnge       CSal_Chnge   ,
        CE.Nsal      CSal_Nsal  , CE.Rem         CSal_TRem    ,
        Emp.Emp_Id   Emp_Id     , Emp.Emp_Num    Emp_Num      ,
        EMP.Emp_Name Emp_Name   , EMP.Emp_Fname  Emp_Fname    ,
        EMP.Dept_Id  Dept_Id    , EMP.Dept_Name  Dept_Name    ,
        EMP.Sect_Id  Sect_Id    , EMP.Sect_Name  Sect_Name    ,
        EMP.Job_Id   Job_Id     , EMP.Job_Name   Job_Name     ,
        EMP.Level_Id Level_Id   , EMP.Level_Name Level_Name   ,
        EMP.Spc1_Id  Spc1_Id    , EMP.Spc1_Name  Spc1_Name    ,
        EMP.Spc2_Id  Spc2_Id    , EMP.Spc2_Name  Spc2_Name    ,
        EMP.Spc3_Id  Spc3_Id    , EMP.Spc3_Name  Spc3_Name    ,
        EMP.Spc4_Id  Spc4_Id    , EMP.Spc4_Name  Spc4_Name    ,
        AF.Id        Affsal_Id  , AF.Name        Affsal_Name  ,
        CT.Id        ChngType_Id, CT.Name        ChngType_Name,
        TX.Id        Tax_Id     , TX.Name        Tax_Name     ,
        C.Perc       Csal_Perc  , C.Amt          Csal_Amt     ,
        C.Nmin       Csal_Nmin  , C.Nmax         Csal_Nmax    ,
        CS.Id        Status_Id  , CS.Name        Status_Name  ,
        C.Rem        Csal_Rem
   From Emp_Csal         C  ,
        Emp_Csalemp      CE ,
        Emp_Cod_Affsal   AF ,
        Emp_Cod_Chngtype CT ,
        Emp_MChSalBrkt   TX ,
        Emp_Vempshort    EMP,
        Phs_Cod_Status   CS
  Where C.Saltyp_Id=AF.Id
    AND C.Type_Id  =CT.Id
    AND C.Brkt_Id  =TX.Id
    AND C.Status_Id=CS.Id
    AND CE.Csal_Id =C.Id
    AND CE.Emp_Id  =EMP.Emp_Id;

