        Cod_Chngtype.Id   Cod_Chngtype_Id, Cod_Chngtype.Name  Cod_Chngtype_Name,
        Sfsal.Nyear       Sfsal_Nyear    ,
        Sfsal.Nmonth      Sfsal_Nmonth   ,
        Sfsal.Perc        Sfsal_Perc     ,
