        Emp_SFSalEmp      Sfsalemp       ,
        Emp_Cod_Aff       Cod_Aff        ,
        Emp_Cod_Affsal    Cod_Affsal     ,
        Emp_Cod_Chngtype  Cod_Chngtype   ,
        Emp_Vempshort     Emp
 Where  Sfsal.Subfrom_Id= Cod_Aff.Id
    AND Sfsal.Saltyp_Id = Cod_Affsal.Id
    AND Sfsal.Type_Id   = Cod_Chngtype.Id
    AND SFSalEmp.SSAL_ID= Sfsal.id
    AND SFSalEmp.EMP_ID = Emp.Emp_Id;
